"""Scrum projects: manager creates a project, picks members, plans a sprint; members work only their own tasks."""
from harness import app_session, Check, run, SHOTS
async def main():
    c = Check('scrum projects')
    async with app_session() as s:
        pg = s.page
        async def tab(k): await pg.click(f'[data-ptab="{k}"]'); await pg.wait_for_timeout(300); return await pg.inner_text('#main')
        await s.sign_in_as('apps-mgr'); await s.go('#/projects'); await pg.click('[data-add="project"]'); await pg.wait_for_selector('#recform')
        await pg.fill('#recform [name=name]', 'OR Direct Booking'); await pg.click('[data-save]'); await pg.wait_for_timeout(300)
        pid = await s.js("Store.all('project').find(p => p.name === 'OR Direct Booking').id")
        c('manager-created project belongs to his team', await s.js(f"(p => p.manager === 'apps-mgr' && p.team === 'apps')(Store.get('{pid}'))"))
        await pg.click('#main tbody tr'); await pg.wait_for_timeout(400); c('row opens the board', (await s.js('location.hash')).startswith('#/project/'))
        await tab('team'); await pg.click('#editmem'); await pg.check('[name=pm][value=yousef]'); await pg.check('[name=pm][value=layla]'); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
        await tab('backlog')
        for title, pts, who in [('Build booking screen', '5', 'yousef'), ('Write test scripts', '3', 'layla'), ('Train OR staff', '2', ''), ('Fix slot overlap bug', '3', 'yousef')]:
            await pg.click('#additem'); await pg.wait_for_selector('#recform'); await pg.fill('#recform [name=title]', title); await pg.select_option('#recform [name=points]', pts)
            if who: await pg.select_option('#recform [name=assignee]', who)
            await pg.click('[data-save]'); await pg.wait_for_timeout(250)
        c('4 backlog items numbered #1-#4', await s.js(f"Scrum.items('{pid}').map(t => t.n).sort().join()") == '1,2,3,4')
        await tab('sprints'); await pg.click('#addsprint'); await pg.wait_for_selector('#recform')
        await pg.fill('#recform [name=start]', await s.js("U.addDays(U.todayStr(), -7)")); await pg.fill('#recform [name=end]', await s.js("U.addDays(U.todayStr(), 6)")); await pg.click('[data-save]'); await pg.wait_for_timeout(300)
        await pg.click('[data-spstart]'); await pg.wait_for_timeout(300)
        sp = await s.js(f"Scrum.active('{pid}').id"); c('sprint started, project now In Progress', bool(sp) and await s.js(f"Store.get('{pid}').status") == 'In Progress')
        await tab('backlog')
        for _ in range(3): await pg.select_option('#main .card:last-of-type [data-tosp] >> nth=0', sp); await pg.wait_for_timeout(250)
        c('3 items pulled into the sprint', await s.js(f"Scrum.items('{pid}').filter(t => t.sprint === '{sp}').length") == 3)
        await s.sign_in_as('yousef'); c('member gets Projects in the menu', await pg.locator('nav [data-nav="projects"]').count() == 1)
        c('member\'s My Day lists project tasks', 'Project task' in await s.go('#/home'))
        await s.go(f'#/project/{pid}')
        await tab('board')
        mine = await s.js(f"Scrum.items('{pid}').find(t => t.title === 'Build booking screen').id")
        for _ in range(3): await pg.click(f'[data-mv="{mine}|1"]'); await pg.wait_for_timeout(250)
        c('member completes his own task', await s.js(f"Store.get('{mine}').status") == 'Done' and bool(await s.js(f"Store.get('{mine}').doneDate")))
        other = await s.js(f"Scrum.items('{pid}').find(t => t.title === 'Write test scripts').id")
        await s.js(f"moveItem('{other}', 'Done')"); await pg.wait_for_timeout(200)
        c("member cannot move someone else's task", await s.js(f"Store.get('{other}').status") == 'To Do')
        await pg.screenshot(path=f'{SHOTS}/scrum_board_member.png', full_page=True)
        await s.sign_in_as('nora'); t = await s.go(f'#/project/{pid}')
        c('same team, not a member: can look but not plan', 'OR Direct Booking' in t and not await s.js(f"Scrum.planner(Store.get('{pid}'))") and not await s.js(f"Scrum.member(Store.get('{pid}'))"))
        await s.sign_in_as('lab-mgr'); c('another team cannot open the project', 'another team' in await s.go(f'#/project/{pid}'))
        await s.sign_in_as('apps-mgr'); await s.go(f'#/project/{pid}'); t = await tab('reports')
        c('burndown drawn', await pg.locator('svg.burn').count() == 1)
        await tab('sprints'); await pg.click('[data-spdone]'); await pg.wait_for_timeout(250); await pg.click('[data-ok]'); await pg.wait_for_timeout(300)
        c('sprint completed: 5 of 10 points', await s.js(f"(x => [x.status, x.donePoints, x.committed].join())(Store.get('{sp}'))") == 'Completed,5,10')
        c('velocity shown after a completed sprint', 'Complete a sprint' not in await tab('reports'))
        c('progress from story points (5/13 = 38%)', await s.js(f"Scrum.progress(Store.get('{pid}'))") == 38)
        await s.sign_in_as('khalid'); c('director sees the team project', 'OR Direct Booking' in await s.go('#/home'))
        c.done(s)
run(main())
